int process_dref_atom(MOVContext *c, AVIOContext *pb, MOVAtom atom) {
    int entries_count = avio_rb32(pb);
    int i;

    if (!c->nb_streams) {
        return AVERROR_INVALIDDATA;
    }

    c->dref_entries = av_malloc(entries_count * sizeof(*c->dref_entries));
    if (!c->dref_entries) {
        return AVERROR(ENOMEM);
    }

    for (i = 0; i < entries_count; i++) {
        uint32_t type = avio_rl32(pb);
        uint16_t version = avio_rb16(pb);
        uint16_t flags = avio_rb16(pb);
        int32_t size = avio_rb32(pb);

        if (size < 0) {
            av_freep(&c->dref_entries);
            return AVERROR_INVALIDDATA;
        }

        if (avio_feof(pb)) {
            av_freep(&c->dref_entries);
            return AVERROR_EOF;
        }

        c->dref_entries[i].type = type;
        c->dref_entries[i].version = version;
        c->dref_entries[i].flags = flags;

        if (type == MKTAG('a','l','i','a')) {
            int32_t alias_size = avio_rb32(pb);
            uint8_t *alias_data = av_malloc(alias_size);

            if (!alias_data) {
                av_freep(&c->dref_entries);
                return AVERROR(ENOMEM);
            }

            if (avio_read(pb, alias_data, alias_size) != alias_size) {
                av_freep(&alias_data);
                av_freep(&c->dref_entries);
                return AVERROR_INVALIDDATA;
            }

            c->dref_entries[i].alias_data = alias_data;
            c->dref_entries[i].alias_size = alias_size;
        } else {
            char *filename = av_malloc(size + 1);

            if (!filename) {
                av_freep(&c->dref_entries);
                return AVERROR(ENOMEM);
            }

            if (avio_read(pb, filename, size) != size) {
                av_freep(&filename);
                av_freep(&c->dref_entries);
                return AVERROR_INVALIDDATA;
            }

            filename[size] = '\0';
            c->dref_entries[i].filename = filename;
        }
    }

    c->nb_dref_entries = entries_count;
    return 0;
}
